import {useCallback,useEffect,useMemo,useRef,useState} from "react";
import {
 Activity,ArrowDown,ArrowDownLeft,ArrowLeftRight,ArrowRight,ArrowUp,ArrowUpRight,
 Bell,BookOpen,Box,Braces,Check,CheckCheck,ChevronDown,ChevronRight,ChevronsUpDown,
 Circle,Clock3,Columns2,CloudDownload,CloudUpload,Code2,Command,Compass,Copy,ExternalLink,
 Eye,FileClock,FileCode2,FileDiff,FilePlus2,FileText,Filter,Folder,FolderGit2,GitBranch,
 GitCommitHorizontal,GitFork,GitMerge,GitPullRequest,GitPullRequestArrow,HardDrive,
 Layers3,LayoutGrid,ListFilter,LoaderCircle,Maximize2,Minus,MoreHorizontal,
 PanelLeftClose,PanelLeftOpen,Plus,RefreshCw,Search,Settings2,ShieldCheck,SlidersHorizontal,
 Sparkles,SquareArrowOutUpRight,Terminal,Trash2,Undo2,Workflow, X
} from "lucide-react";
import type{LucideIcon}from "lucide-react";
import {client}from "./api";
import TerminalDock,{type TerminalRequest} from "./TerminalDock";
import ConflictResolver from "./ConflictResolver";
import SideBySideDiff from "./SideBySideDiff";
import FileInsights from "./FileInsights";
import {buildGraph,graphPalette}from "./graph";
import type{ChangedFile,Commit,DiffHunk,FileComparison,ProviderPr,ProviderRun,Ref,Repository,Worktree}from "./types";

type Route="history"|"worktrees"|"launchpad"|"agents"|"settings";
type ActionDialog={title:string;description:string;label:string;placeholder?:string;defaultValue?:string;confirmText:string;danger?:boolean;onConfirm:(value:string)=>void};
const first=(path:string)=>path.replaceAll("\\","/").split("/").filter(Boolean).at(-1)||path;
const short=(sha:string)=>sha.slice(0,8);
const branchColor=(s:string)=>graphPalette[Math.abs([...s].reduce((n,c)=>((n*31)+c.charCodeAt(0))|0,7))%graphPalette.length];
const hasTauri=()=>typeof window!=="undefined"&&("__TAURI_INTERNALS__" in window);
const statusCode=(f:ChangedFile)=>f.conflict?"!":f.untracked?"+":(f.staged?f.x:f.y).trim()||"M";
const relative=(text:string)=>{if(!text)return"";const d=new Date(text);if(isNaN(d.getTime()))return text;const days=Math.round((Date.now()-d.getTime())/86400000);return days===0?"Today":days===1?"Yesterday":days<30?days+"d ago":d.toLocaleDateString(undefined,{month:"short",day:"numeric"});};
const iconFor=(f:ChangedFile)=>f.conflict?"conflict":f.untracked?"added":f.staged?"staged":"edited";
const groupRef=(r:Ref)=>r.kind==="local"?"Local branches":r.kind==="remote"?"Remotes":"Tags";
const palette=["#73d6cc","#b79fff","#ecb582","#8fbdf4","#de9eca","#bed592"];

function Mark({size=28}:{size?:number}){return <svg width={size} height={size} viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M7 31 19.9 8.5 33 31" stroke="currentColor" strokeWidth="3.8" strokeLinecap="round" strokeLinejoin="round"/><path d="M11.5 25.8h17.3" stroke="#74d8d2" strokeWidth="3.8" strokeLinecap="round"/><circle cx="20" cy="8.5" r="3.5" fill="#f4b583"/><circle cx="7" cy="31" r="2.7" fill="#74d8d2"/><circle cx="33" cy="31" r="2.7" fill="#b5a0f6"/></svg>}
function IButton({icon:Icon,label,onClick,active=false,disabled=false,kind=""}:{icon:LucideIcon;label:string;onClick:()=>void;active?:boolean;disabled?:boolean;kind?:string}){return <button type="button" className={"icon-btn "+kind+(active?" active":"")} aria-label={label} title={label} onClick={onClick} disabled={disabled}><Icon size={16} strokeWidth={1.8}/></button>}
function ActionButton({icon:Icon,label,onClick,primary=false,disabled=false,busy=false}:{icon:LucideIcon;label:string;onClick:()=>void;primary?:boolean;disabled?:boolean;busy?:boolean}){return <button type="button" className={"action-btn"+(primary?" primary":"")} disabled={disabled||busy} onClick={onClick}>{busy?<LoaderCircle className="spin" size={15}/>:<Icon size={15} strokeWidth={1.85}/>}<span>{label}</span></button>}
function Pill({children,color}:{children:React.ReactNode;color?:string}){return <span className="pill" style={color?{"--pill-color":color} as React.CSSProperties:{}}>{children}</span>}
function Section({title,count,icon:Icon,open,onToggle,children,accent}:{title:string;count?:number;icon:LucideIcon;open:boolean;onToggle:()=>void;children:React.ReactNode;accent?:string}){return <section className="reference-section"><button className="section-header" onClick={onToggle}><Icon size={14} color={accent||"currentColor"} strokeWidth={1.9}/><span>{title}</span><span className="section-count">{count||0}</span>{open?<ChevronDown size={14}/>:<ChevronRight size={14}/>}</button>{open&&<div className="section-items">{children}</div>}</section>}
function CommitGlyph({row,focused}:{row:ReturnType<typeof buildGraph>[number];focused:boolean}){const p=(n:number)=>15+n*17;const center=18;return <svg className="commit-glyph" width="188" height="36" viewBox="0 0 188 36" aria-hidden="true">
 {row.edges.map((e,i)=>{const colour=graphPalette[(e.type==="through"?e.start:e.end)%graphPalette.length];return e.type==="through"?<path key={i} d={"M"+p(e.start)+" 0 V36"} stroke={colour} strokeWidth="2.1" fill="none" opacity=".8"/>:<path key={i} d={"M"+p(e.start)+" 18 C"+p(e.start)+" 28 "+p(e.end)+" 25 "+p(e.end)+" 36"} stroke={colour} strokeWidth="2.2" fill="none"/>;})}
 <path d={"M"+p(row.lane)+" 0 V18"} stroke={graphPalette[row.lane%graphPalette.length]} strokeWidth="2.2" fill="none"/>
 <circle cx={p(row.lane)} cy={center} r={focused?7:6} fill="#111922" stroke={graphPalette[row.lane%graphPalette.length]} strokeWidth={focused?2.6:2.3}/>
 <circle cx={p(row.lane)} cy={center} r="2.2" fill={graphPalette[row.lane%graphPalette.length]}/>
 </svg>}
function DiffLines({text}:{text:string}){if(!text)return <div className="diff-placeholder"><FileDiff size={26}/><b>Choose a file to inspect</b><span>The patch will appear here without changing your working tree.</span></div>;
 const lines=text.split(/\r?\n/).slice(0,1400);
 return <div className="diff-code" role="region" aria-label="Git diff">{lines.map((line,i)=>{const type=line.startsWith("+")&&!line.startsWith("+++")?"added":line.startsWith("-")&&!line.startsWith("---")?"removed":line.startsWith("@@")?"hunk":/^(diff |index |---|\\+\\+\\+|new file |deleted file )/.test(line)?"meta":"";return <div key={i} className={"diff-line "+type}><span className="line-no">{i+1}</span><span className="line-source">{line||" "}</span></div>})}{text.split(/\r?\n/).length>1400&&<p className="diff-truncated">Large diff truncated for display.</p>}</div>;
}
function Dialog({dialog,onClose}:{dialog:ActionDialog;onClose:()=>void}){const[value,setValue]=useState(dialog.defaultValue||"");return <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal" role="dialog" aria-modal="true" aria-label={dialog.title}><div className="modal-top"><span className="modal-icon"><GitBranch size={20}/></span><IButton icon={X} label="Close" onClick={onClose}/></div><h2>{dialog.title}</h2><p>{dialog.description}</p><label className="field-label" htmlFor="dialog-input">{dialog.label}</label><input id="dialog-input" autoFocus value={value} placeholder={dialog.placeholder} onChange={e=>setValue(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&value.trim()){dialog.onConfirm(value.trim());onClose();}if(e.key==="Escape")onClose();}}/><div className="dialog-actions"><button className="quiet-btn" onClick={onClose}>Cancel</button><button className={"dialog-confirm"+(dialog.danger?" danger":"")} disabled={!value.trim()} onClick={()=>{dialog.onConfirm(value.trim());onClose();}}>{dialog.confirmText}<ArrowRight size={15}/></button></div></div></div>;}
function Empty({onOpen,recent}:{onOpen:()=>void;recent:string[]}){return <div className="empty-home"><div className="empty-orbit"><div className="orbit-a"/><div className="orbit-b"/><div className="orbit-c"/><span className="orbit-mark"><Mark size={74}/></span><span className="orbit-node n1"/><span className="orbit-node n2"/><span className="orbit-node n3"/></div><div className="empty-copy"><span className="eyebrow">VERSION CONTROL, IN FOCUS</span><h1>Every branch.<br/><em>One clear picture.</em></h1><p>Bring your repositories, worktrees and Git history together in a workspace built for focus and control.</p><button className="launch-btn" onClick={onOpen}><FolderGit2 size={18}/>Open a repository<ArrowRight size={17}/></button><div className="welcome-hint"><Command size={13}/> Press Ctrl+P for quick actions</div></div>{recent.length>0&&<div className="empty-recents">{recent.slice(0,4).map(x=><span key={x}><Folder size={15}/>{first(x)}</span>)}</div>}</div>;}
function BlankRoute({icon:Icon,title,body}:{icon:LucideIcon;title:string;body:string}){return <div className="blank-route"><div className="blank-icon"><Icon size={28}/></div><h2>{title}</h2><p>{body}</p></div>;}

export default function App(){
 const[recent,setRecent]=useState<string[]>([]);
 const[path,setPath]=useState("");
 const[repo,setRepo]=useState<Repository|null>(null);
 const[commits,setCommits]=useState<Commit[]>([]);
 const[hasMore,setHasMore]=useState(false);
 const[histLoading,setHistLoading]=useState(false);
 const[loading,setLoading]=useState(false);
 const[busy,setBusy]=useState("");
 const[error,setError]=useState("");
 const[success,setSuccess]=useState("");
 const[route,setRoute]=useState<Route>("history");
 const[selection,setSelection]=useState<string>("WIP");
 const[refScope,setRefScope]=useState("all");
 const[historyQuery,setHistoryQuery]=useState("");
 const[refQuery,setRefQuery]=useState("");
 const[collapsed,setCollapsed]=useState<Record<string,boolean>>({});
 const[leftWidth,setLeftWidth]=useState(256);
 const[rightWidth,setRightWidth]=useState(376);
 const[showLeft,setShowLeft]=useState(true);
 const[diff,setDiff]=useState("");
 const[comparison,setComparison]=useState<FileComparison|null>(null);
 const[expandedDiff,setExpandedDiff]=useState(false);
 const[hunks,setHunks]=useState<DiffHunk[]>([]);
 const[diffMode,setDiffMode]=useState<"patch"|"hunks"|"side">("patch");
 const[diffTitle,setDiffTitle]=useState("");
 const[selectedFile,setSelectedFile]=useState("");
 const[commitText,setCommitText]=useState("");
 const[commitBody,setCommitBody]=useState("");
 const[dialog,setDialog]=useState<ActionDialog|null>(null);
 const[paletteOpen,setPaletteOpen]=useState(false);
 const[conflictFile,setConflictFile]=useState<string|null>(null);
 const[insightsFile,setInsightsFile]=useState<string|null>(null);
 const[terminalDockOpen,setTerminalDockOpen]=useState(false);
 const[terminalRequest,setTerminalRequest]=useState<TerminalRequest|null>(null);
 const terminalSeq=useRef(0);
 const[operationsOpen,setOperationsOpen]=useState(false);
 const[paletteQuery,setPaletteQuery]=useState("");
 const[providerLoading,setProviderLoading]=useState(false);
 const[prs,setPrs]=useState<ProviderPr[]>([]);
 const[runs,setRuns]=useState<ProviderRun[]>([]);
 const[theme,setTheme]=useState<"dark"|"light">(()=>localStorage.getItem("arclane-theme")==="light"?"light":"dark");
 const version=useRef(0);
 const diffVersion=useRef(0);
 const token=useRef(0);
 const currentCommit=commits.find(x=>x.sha===selection)||null;
 const graph=useMemo(()=>buildGraph(commits),[commits]);
 const refs=useMemo(()=>repo?.refs||[],[repo]);
 const refsByGroup=useMemo(()=>({
  "Local branches":refs.filter(x=>x.kind==="local"),
  "Remotes":refs.filter(x=>x.kind==="remote"),
  "Tags":refs.filter(x=>x.kind==="tag")
 }),[refs]);
 const filtered=useMemo(()=>graph.filter(x=>!historyQuery.trim()||[x.subject,x.author,x.sha,...(refs.filter(r=>x.sha.startsWith(r.sha)).map(r=>r.name))].some(s=>s.toLowerCase().includes(historyQuery.toLowerCase()))),[graph,historyQuery,refs]);
 const graphScrollRef=useRef<HTMLDivElement|null>(null);
 const[graphScrollTop,setGraphScrollTop]=useState(0);
 const[graphViewportHeight,setGraphViewportHeight]=useState(540);
 const graphRowHeight=36;
 const graphStart=Math.max(0,Math.floor(Math.max(0,graphScrollTop-graphRowHeight)/graphRowHeight)-8);
 const graphCapacity=Math.max(25,Math.ceil(graphViewportHeight/graphRowHeight)+18);
 const visibleGraph=filtered.slice(graphStart,graphStart+graphCapacity);
 const graphBelow=Math.max(0,(filtered.length-graphStart-visibleGraph.length)*graphRowHeight);
 useEffect(()=>{const node=graphScrollRef.current;if(!node||route!=="history")return;const measure=()=>setGraphViewportHeight(node.clientHeight);measure();const observer=new ResizeObserver(measure);observer.observe(node);return()=>observer.disconnect();},[route,path]);
 useEffect(()=>{const node=graphScrollRef.current;if(node)node.scrollTop=0;setGraphScrollTop(0);},[historyQuery,refScope,path]);
 const wip=selection==="WIP";
 const staged=repo?.files.filter(f=>f.staged)||[];
 const unstaged=repo?.files.filter(f=>f.unstaged||f.untracked||f.conflict)||[];
 const showToast=(message:string)=>{setSuccess(message);window.setTimeout(()=>setSuccess(""),4200);};
 const fail=(err:unknown)=>{setError(err instanceof Error?err.message:String(err));setBusy("");setLoading(false);};
 const refresh=useCallback(async(repoPath:string,scope="all")=>{
  const t=++version.current;
  setLoading(true);setError("");setHistLoading(false);
  try{const[state,page]=await Promise.all([client.inspect(repoPath),client.history(repoPath,350,scope,0)]);if(t!==version.current)return;
   setRepo(state);setCommits(page.commits);setHasMore(page.has_more);setSelection("WIP");setDiff("");setComparison(null);setHunks([]);setSelectedFile("");setLoading(false);}
  catch(e){if(t===version.current)fail(e);}
 },[]);
 const loadPath=useCallback(async(next:string)=>{
   if(!next)return;setPath(next);setRoute("history");setRefScope("all");setCommitText("");setCommitBody("");setRepo(null);setCommits([]);
   await refresh(next);
 },[refresh]);
 useEffect(()=>{let gone=false;if(!hasTauri()){setError("Open the Arclane desktop application to connect to Git. The standalone browser view does not access local repositories.");return;}
   client.recent().then(paths=>{if(gone)return;setRecent(paths);if(paths.length)void loadPath(paths[0]);}).catch(fail);return()=>{gone=true;};},[loadPath]);
 useEffect(()=>{localStorage.setItem("arclane-theme",theme);document.documentElement.dataset.theme=theme;},[theme]);
 const openRepo=async()=>{try{const next=await client.pick();if(!next)return;const paths=[next,...recent.filter(x=>x.toLowerCase()!==next.toLowerCase())];await client.setRecent(paths);setRecent(paths);void loadPath(next);}catch(e){fail(e);}};
 const chooseRepo=(next:string)=>{void loadPath(next);setRecent(all=>{const arr=[next,...all.filter(x=>x!==next)];void client.setRecent(arr);return arr;});};
 const initializeRepository=async()=>{try{const folder=await client.pick();if(!folder)return;setDialog({title:"Initialize Git repository",description:"Create a new .git directory in the selected folder. This is refused if the folder is inside an existing Git repository. Type INIT to confirm.",label:"Confirmation",placeholder:"INIT",confirmText:"Initialize repository",onConfirm:value=>{if(value!=="INIT"){fail(new Error("Confirmation did not match"));return;}void client.initialize(folder).then(async result=>{const paths=[result.path,...recent.filter(x=>x!==result.path)];await client.setRecent(paths);setRecent(paths);await loadPath(result.path);showToast("Repository initialized");}).catch(fail);}});}catch(e){fail(e);}};
 const cloneRepository=()=>{setDialog({title:"Clone a repository",description:"Enter an HTTPS/SSH URL or an existing absolute local Git repository path. Afterward choose the parent folder for a new checkout. The clone never overwrites an existing folder.",label:"Repository URL or local path",placeholder:"https://github.com/owner/repository.git",confirmText:"Choose clone location",onConfirm:url=>{void (async()=>{try{const parent=await client.pick();if(!parent)return;setBusy("clone");const result=await client.clone(url,parent);const paths=[result.path,...recent.filter(x=>x!==result.path)];await client.setRecent(paths);setRecent(paths);await loadPath(result.path);showToast("Repository cloned");}catch(e){fail(e);}finally{setBusy("");}})();}});};
 const setScope=async(scope:string)=>{if(!path)return;setRefScope(scope);setLoading(true);setError("");const t=++version.current;try{const page=await client.history(path,350,scope);if(t!==version.current)return;setCommits(page.commits);setHasMore(page.has_more);setSelection("WIP");setDiff("");setLoading(false);}catch(e){if(t===version.current)fail(e);}};
 const loadMore=async()=>{if(!path||histLoading||!hasMore)return;setHistLoading(true);try{const page=await client.history(path,350,refScope,commits.length);setCommits(old=>{const existing=new Set(old.map(x=>x.sha));return [...old,...page.commits.filter(x=>!existing.has(x.sha))]});setHasMore(page.has_more);}catch(e){fail(e);}finally{setHistLoading(false);}};
 const inspectCommit=async(commit:Commit)=>{setSelection(commit.sha);setDiffTitle("Commit "+short(commit.sha));setSelectedFile("");setComparison(null);setHunks([]);setDiffMode("patch");const n=++diffVersion.current;try{const data=await client.diff(path,"",false,commit.sha);if(n===diffVersion.current)setDiff(data.text);}catch(e){if(n===diffVersion.current)fail(e);}};
 const inspectFile=async(file:ChangedFile,isStaged:boolean)=>{setSelection("WIP");setSelectedFile(file.path+(isStaged?"#staged":""));setDiffTitle(file.path);setDiff("");setComparison(null);setHunks([]);setDiffMode("side");const n=++diffVersion.current;try{const results=await Promise.allSettled([client.diff(path,file.path,isStaged),client.hunks(path,file.path,isStaged),client.compare(path,file.path,isStaged)]);if(n!==diffVersion.current)return;if(results[0].status==="fulfilled")setDiff(results[0].value.text);else fail(results[0].reason);setHunks(results[1].status==="fulfilled"?results[1].value.hunks:[]);if(results[2].status==="fulfilled"){setComparison(results[2].value);}else{setComparison(null);setDiffMode(old=>old==="side"?"patch":old);}}catch(e){if(n===diffVersion.current)fail(e);}};
 const stageHunk=async(index:number)=>{if(!path||!selectedFile||busy)return;const staged=selectedFile.endsWith("#staged"),file=staged?selectedFile.slice(0,-7):selectedFile;setBusy("hunk");setError("");try{await client.applyHunk(path,file,staged,index);showToast((staged?"Unstaged":"Staged")+" selected hunk");await refresh(path,refScope);const next=await Promise.allSettled([client.diff(path,file,staged),client.hunks(path,file,staged)]);setSelection("WIP");setSelectedFile(file+(staged?"#staged":""));setDiffTitle(file);setDiffMode("hunks");setDiff(next[0].status==="fulfilled"?next[0].value.text:"");setHunks(next[1].status==="fulfilled"?next[1].value.hunks:[]);}catch(e){fail(e);}finally{setBusy("");}};
 const runAction=async(op:string,file:string|null=null,input:string|null=null):Promise<boolean>=>{if(!path||busy)return false;setBusy(op);setError("");try{const res=await client.action(path,op,file,input);showToast(res.output||"Git "+op.replaceAll("_"," ")+" completed");await refresh(path,refScope);return true;}catch(e){const message=e instanceof Error?e.message:String(e);await refresh(path,refScope);setError(message);return false;}finally{setBusy("");}};
 const stageAll=()=>{if((repo?.stats.conflicts||0)>0){setError("Resolve all merge conflicts before staging all changes.");return;}void runAction("stage_all");};
 const commit=async()=>{if(!commitText.trim())return;const text=commitText.trim()+(commitBody.trim()?"\n\n"+commitBody.trim():"");if(await runAction("commit",null,text)){setCommitText("");setCommitBody("");}};
 const askOperation=(op:string,title:string,description:string,label:string,placeholder:string,confirmText:string,file:string|null=null,danger=false)=>{
   setOperationsOpen(false);
   setDialog({title,description,label,placeholder,confirmText,danger,onConfirm:v=>void runAction(op,file,v)});
 };
 const guardedOperation=(op:string,target:string,title:string,description:string,confirmation:string,file:string|null=null)=>{
   setOperationsOpen(false);
   setDialog({title,description:description+" Type "+confirmation+" to confirm.",label:"Confirmation",placeholder:confirmation,confirmText:title,danger:true,onConfirm:v=>{
     if(v!==confirmation){fail(new Error("Confirmation did not match. No Git command was run."));return;}
     void runAction(op,file,target);
   }});
 };
 const branch=()=>{setDialog({title:"Create a branch",description:"Name your new branch. Arclane will create it at HEAD and switch to it.",label:"Branch name",placeholder:"feature/my-next-step",confirmText:"Create branch",onConfirm:v=>void runAction("branch_create",null,v)});};
 const openProvider=async()=>{if(!path)return;setProviderLoading(true);setError("");const res=await Promise.allSettled([client.prs(path),client.runs(path)]);if(res[0].status==="fulfilled")setPrs(res[0].value);else fail(res[0].reason);if(res[1].status==="fulfilled")setRuns(res[1].value);else fail(res[1].reason);setProviderLoading(false);};
 const changeRoute=(r:Route)=>{setRoute(r);if(r==="launchpad")void openProvider();};
 const showTerminal=(folder:string)=>{if(!folder)return;setTerminalRequest({path:folder,sequence:++terminalSeq.current});setTerminalDockOpen(true);};
 const actions:{name:string;icon:LucideIcon;shortcut?:string;perform:()=>void}[]=[
  {name:"Open repository",icon:FolderGit2,shortcut:"Ctrl+O",perform:()=>void openRepo()},
  {name:"Clone repository",icon:CloudDownload,perform:cloneRepository},
  {name:"Initialize a repository",icon:FolderGit2,perform:()=>void initializeRepository()},
  {name:"Refresh repository",icon:RefreshCw,shortcut:"F5",perform:()=>path&&void refresh(path,refScope)},
  {name:"History and commit graph",icon:GitCommitHorizontal,perform:()=>changeRoute("history")},
  {name:"Create branch",icon:GitBranch,perform:branch},
  {name:"Rename branch",icon:GitBranch,perform:()=>askOperation("branch_rename","Rename branch","Rename the currently checked-out branch. The Git branch reference will be updated.", "New branch name","feature/renamed","Rename branch",repo?.branch||null)},
  {name:"Delete merged branch",icon:Trash2,perform:()=>askOperation("branch_delete","Delete a merged branch","Git refuses to delete unmerged branches. Type the exact branch name to delete.", "Branch to delete","feature/old","Delete merged branch",null,true)},
  {name:"Create lightweight tag",icon:Box,perform:()=>askOperation("tag_create","Create Git tag","Create a lightweight tag at HEAD.","Tag name","v1.0.0","Create tag")},
  {name:"Delete tag",icon:Trash2,perform:()=>askOperation("tag_delete","Delete Git tag","Delete a local tag. Existing remote tags are not changed.","Tag name","v1.0.0","Delete tag",null,true)},
  {name:"Merge branch into current",icon:GitMerge,perform:()=>askOperation("merge","Merge branch","Merge an existing local branch into the checked-out branch. Git will stop safely if conflicts need resolution.","Branch to merge","feature/ready","Merge branch")},
  {name:"Rebase current branch onto another",icon:GitFork,perform:()=>askOperation("rebase","Rebase branch","Rebase current commits onto another local branch. This rewrites commit hashes. Avoid rebasing published shared history.","Target branch","main","Rebase current branch",null,true)},
  {name:"Cherry-pick selected commit",icon:GitCommitHorizontal,perform:()=>currentCommit&&void runAction("cherry_pick",null,currentCommit.sha)},
  {name:"Revert selected commit",icon:Undo2,perform:()=>currentCommit&&guardedOperation("revert",currentCommit.sha,"Revert commit","Create a new commit reversing the selected commit.",short(currentCommit.sha))},
  {name:"Stash changes including untracked",icon:Layers3,perform:()=>askOperation("stash","Stash working changes","Temporarily store current tracked and untracked changes.", "Stash message","Work in progress","Stash changes")},
  {name:"Continue conflicted operation",icon:Check,perform:()=>void runAction(repo?.sequencer?.merge?"merge_continue":repo?.sequencer?.rebase?"rebase_continue":repo?.sequencer?.cherry_pick?"cherry_pick_continue":"merge_continue")},
  {name:"Abort conflicted operation",icon:X,perform:()=>void runAction(repo?.sequencer?.merge?"merge_abort":repo?.sequencer?.rebase?"rebase_abort":repo?.sequencer?.cherry_pick?"cherry_pick_abort":repo?.sequencer?.revert?"revert_abort":"merge_abort")},
  {name:"Reset current branch to selected commit (soft)",icon:Undo2,perform:()=>currentCommit&&guardedOperation("reset_soft",currentCommit.sha,"Soft reset","Move your current branch pointer. Staged and working files are retained.",short(currentCommit.sha))},
  {name:"Reset current branch to selected commit (mixed)",icon:Undo2,perform:()=>currentCommit&&guardedOperation("reset_mixed",currentCommit.sha,"Mixed reset","Move your current branch pointer and unstage files. Working files are retained.",short(currentCommit.sha))},
  {name:"Update Git submodules",icon:Box,perform:()=>void runAction("submodule_update")},
  {name:"Fetch remotes",icon:CloudDownload,perform:()=>void runAction("fetch")},
  {name:"Pull (fast-forward only)",icon:ArrowDown,perform:()=>void runAction("pull")},
  {name:"Push current branch",icon:ArrowUp,perform:()=>void runAction("push")},
  {name:"View worktrees",icon:GitFork,perform:()=>changeRoute("worktrees")},
  {name:"View agent worktrees",icon:Braces,perform:()=>changeRoute("agents")},
  {name:"Pull requests and checks",icon:GitPullRequest,perform:()=>changeRoute("launchpad")},
  {name:"Preferences",icon:Settings2,perform:()=>changeRoute("settings")},
  {name:"Open repository in VS Code",icon:Code2,perform:()=>path&&void client.openPath(path,"editor").catch(fail)},
  {name:"Open embedded terminal tab",icon:Terminal,perform:()=>showTerminal(path)}
 ];
 useEffect(()=>{const handler=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&["p","k"].includes(e.key.toLowerCase())){e.preventDefault();setPaletteOpen(s=>!s);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="o"){e.preventDefault();void openRepo();}if(e.key==="F5"){e.preventDefault();if(path)void refresh(path,refScope);}if(e.key==="Escape"){setPaletteOpen(false);setDialog(null);}};document.addEventListener("keydown",handler);return()=>document.removeEventListener("keydown",handler);});
 const renderFiles=(files:ChangedFile[],isStaged:boolean)=><div className="change-list">{files.map(file=><div key={file.path} className={"change-row"+(selectedFile===file.path+(isStaged?"#staged":"")?" selected":"")}><button className="change-select" onClick={()=>file.conflict?setConflictFile(file.path):void inspectFile(file,isStaged)}><span className={"file-flag "+iconFor(file)}>{statusCode(file)}</span><span className="file-label"><span className="file-name">{first(file.path)}</span><span className="file-folder">{file.path.includes("/")?file.path.slice(0,file.path.lastIndexOf("/")):"Repository root"}</span></span></button>{file.conflict?<button className="change-resolve" onClick={()=>setConflictFile(file.path)}><GitMerge size={13}/>Resolve</button>:<button className="change-mini" aria-label={(isStaged?"Unstage ":"Stage ")+file.path} title={(isStaged?"Unstage ":"Stage ")+file.path} onClick={()=>void runAction(isStaged?"unstage":"stage",file.path)}>{isStaged?<Minus size={14}/>:<Plus size={14}/>}</button>}{!isStaged&&!file.untracked&&!file.conflict&&<button className="change-mini file-discard" aria-label={"Discard unstaged changes in "+file.path} title="Discard unstaged changes (confirmation required)" onClick={()=>guardedOperation("discard_file","","Discard file changes","This permanently discards unstaged changes in "+file.path+". Staged changes remain intact.","DISCARD",file.path)}><Trash2 size={13}/></button>}{!file.untracked&&<button className="change-mini" aria-label={"File history and blame "+file.path} title="File history and line-by-line blame" onClick={()=>setInsightsFile(file.path)}><FileClock size={14}/></button>}</div>)}{files.length===0&&<div className="list-zero">{isStaged?"No staged changes":"Working tree is clean"}</div>}</div>;
 const visibleRefs=(key:keyof typeof refsByGroup)=>refsByGroup[key].filter(r=>!refQuery||r.name.toLowerCase().includes(refQuery.toLowerCase()));
 const nav:{route:Route;icon:LucideIcon;label:string}[]=[
  {route:"history",icon:Workflow,label:"Commit graph"},
  {route:"worktrees",icon:GitFork,label:"Worktrees"},
  {route:"launchpad",icon:GitPullRequestArrow,label:"Pull requests and CI"},
  {route:"agents",icon:Braces,label:"Agent worktrees"},
  {route:"settings",icon:Settings2,label:"Preferences"}
 ];
 const heading:Record<Route,string>={history:"Commit history",worktrees:"Worktrees",launchpad:"Launchpad",agents:"Agent sessions",settings:"Preferences"};
 return <div className="desktop">
  <header className="app-top">
   <div className="brand"><span className="brand-mark"><Mark size={23}/></span><span className="brand-name">arclane</span><span className="brand-version">PREVIEW</span></div>
   <div className="tab-area">{recent.slice(0,5).map((r)=><button key={r} className={"repo-tab"+(path===r?" chosen":"")} onClick={()=>chooseRepo(r)}><FolderGit2 size={14}/><span>{first(r)}</span>{path===r&&<span className="tab-dot"/>}</button>)}<IButton icon={Plus} label="Open another repository" onClick={()=>void openRepo()}/></div>
   <div className="app-top-end"><span className="top-system"><Circle size={6} fill="#68c7ad" color="#68c7ad"/> Local workspace</span><span className="top-divider"/><IButton icon={Bell} label="Show status" onClick={()=>showToast("No background services. Refresh only when requested.")}/></div>
  </header>
  <div className="main-toolbar">
   <div className="repo-identity"><IButton icon={showLeft?PanelLeftClose:PanelLeftOpen} label="Toggle references" onClick={()=>setShowLeft(x=>!x)}/><span className="toolbar-sep"/>{repo?<><span className="identity-mark"><FolderGit2 size={18}/></span><span className="identity-text"><b>{repo.name}</b><small>{repo.branch||"Detached HEAD"}</small></span><span className="identity-tracking">{repo.ahead>0&&<span className="ahead">↑ {repo.ahead}</span>}{repo.behind>0&&<span className="behind">↓ {repo.behind}</span>}</span></>:<><span className="identity-mark muted"><FolderGit2 size={19}/></span><span className="identity-text"><b>No repository open</b><small>Local · Offline ready</small></span></>}</div>
   <button className="quick-search" onClick={()=>setPaletteOpen(true)}><Search size={15}/><span>Search actions, repositories, commits...</span><kbd>Ctrl P</kbd></button>
   <div className="toolbar-actions"><IButton icon={Undo2} label="Undo (not yet available for this action)" onClick={()=>showToast("Undo history is not implemented in this build; Git reflog is available.")} disabled={!repo}/><span className="toolbar-sep"/><ActionButton icon={CloudDownload} label="Fetch" onClick={()=>void runAction("fetch")} disabled={!repo} busy={busy==="fetch"}/><ActionButton icon={ArrowDownLeft} label="Pull" onClick={()=>void runAction("pull")} disabled={!repo} busy={busy==="pull"}/><ActionButton icon={ArrowUpRight} label="Push" onClick={()=>void runAction("push")} primary disabled={!repo} busy={busy==="push"}/><span className="toolbar-sep"/><IButton icon={MoreHorizontal} label="Repository operations" active={operationsOpen} onClick={()=>setOperationsOpen(v=>!v)}/></div>
  </div>
  {operationsOpen&&<div className="operations-menu" role="menu" aria-label="Repository operations"><div className="operations-heading"><GitMerge size={15}/> Git operations <IButton icon={X} label="Close menu" onClick={()=>setOperationsOpen(false)}/></div>{actions.filter(a=>!["Open repository","Refresh repository","History and commit graph","Pull requests and checks","Preferences","Open repository in VS Code","Open terminal in repository"].includes(a.name)).map(a=><button key={a.name} role="menuitem" disabled={!repo} onClick={()=>{a.perform();setOperationsOpen(false);}}><a.icon size={15}/>{a.name}</button>)}</div>}
  <div className="work-layout" style={{"--side-width":showLeft?leftWidth+"px":"0px","--right-width":path?rightWidth+"px":"0px"} as React.CSSProperties}>
   <nav className="icon-rail" aria-label="Sections"><div className="rail-group">{nav.slice(0,4).map(n=><button key={n.route} aria-label={n.label} title={n.label} onClick={()=>changeRoute(n.route)} className={"rail-link"+(route===n.route?" active":"")}><n.icon size={19} strokeWidth={1.8}/></button>)}</div><div className="rail-bottom"><IButton icon={Terminal} label="Open embedded terminal" disabled={!repo} onClick={()=>showTerminal(path)}/><button className={"rail-link"+(route==="settings"?" active":"")} title="Preferences" aria-label="Preferences" onClick={()=>changeRoute("settings")}><Settings2 size={19}/></button></div></nav>
   {showLeft&&<aside className="sidebar">
    <div className="sidebar-top"><div className="pane-eyebrow">NAVIGATOR <span> / {repo?"REPOSITORY":"WORKSPACE"}</span></div><div className="side-title-row"><h2>Explore</h2><IButton icon={MoreHorizontal} label="Navigator actions" onClick={()=>setPaletteOpen(true)}/></div><div className="switcher"><button className={route!=="agents"?"active":""} onClick={()=>changeRoute("history")}><ListFilter size={14}/>References</button><button className={route==="agents"?"active":""} onClick={()=>changeRoute("agents")}><Braces size={14}/>Agents</button></div><div className="filter-wrap"><Search size={15}/><input aria-label="Filter repository references" placeholder="Filter branches, tags..." value={refQuery} onChange={e=>setRefQuery(e.target.value)}/>{refQuery&&<button title="Clear filter" onClick={()=>setRefQuery("")}><X size={13}/></button>}</div></div>
    <div className="sidebar-scroll">{repo?<><div className="sidebar-current"><div className="current-indicator"><GitBranch size={15}/></div><div><small>CURRENT BRANCH</small><strong>{repo.branch||"Detached HEAD"}</strong></div><span className="current-pulse"/></div>{(Object.keys(refsByGroup) as Array<keyof typeof refsByGroup>).map(key=><Section key={key} title={key} count={refsByGroup[key].length} icon={key==="Local branches"?GitBranch:key==="Remotes"?CloudDownload:Box} open={!collapsed[key]} onToggle={()=>setCollapsed(old=>({...old,[key]:!old[key]}))} accent={key==="Local branches"?"#75d9d1":undefined}>{visibleRefs(key).map(r=><button key={r.full} title={r.full} className={"ref-row"+(refScope===r.full?" active":"")} onClick={()=>void setScope(r.full)}><span className="branch-stem" style={{background:branchColor(r.full)}}/><span className="ref-name">{r.name}</span>{r.current&&<span className="ref-head">HEAD</span>}</button>)}{visibleRefs(key).length===0&&<span className="list-zero">No matches</span>}</Section>)}<Section title="Stashes" count={repo.stashes.length} icon={Layers3} open={!collapsed.Stashes} onToggle={()=>setCollapsed(old=>({...old,Stashes:!old.Stashes}))}>{repo.stashes.map(s=><div className="stash-row" key={s.id}><span>{s.id}</span><small title={s.title}>{s.title}</small><span className="stash-actions"><button aria-label={"Apply "+s.id} title="Apply without dropping" onClick={()=>void runAction("stash_apply",null,s.id)}><Undo2 size={13}/></button><button aria-label={"Pop "+s.id} title="Apply and drop" onClick={()=>void runAction("stash_pop",null,s.id)}><ArrowDown size={13}/></button><button aria-label={"Delete "+s.id} title="Delete stash" onClick={()=>guardedOperation("stash_drop",s.id,"Delete stash","This permanently drops the selected local stash.",s.id)}><Trash2 size={13}/></button></span></div>)}</Section><Section title="Worktrees" count={repo.worktrees.length} icon={GitFork} open={!collapsed.Worktrees} onToggle={()=>setCollapsed(old=>({...old,Worktrees:!old.Worktrees}))}>{repo.worktrees.map(w=><button className="ref-row" key={w.path} onClick={()=>changeRoute("worktrees")}><span className="branch-stem" style={{background:"#b1a1ff"}}/><span className="ref-name">{w.branch||first(w.path)}</span>{w.main&&<span className="ref-head">MAIN</span>}</button>)}</Section></>:<div className="sidebar-first"><FolderGit2 size={26}/><h3>Nothing to navigate yet</h3><p>Open a local Git repository to explore its history and branches.</p><button className="text-action" onClick={()=>void openRepo()}>Open repository <ArrowRight size={14}/></button></div>}</div>
    <div className="sidebar-footer"><ActionButton icon={GitBranch} label="New branch" onClick={branch} disabled={!repo}/><IButton icon={Plus} label="Add repository" onClick={()=>void openRepo()}/></div>
   </aside>}
   {showLeft&&<div className="resize-rail" role="separator" title="Resize navigator" onPointerDown={e=>{e.currentTarget.setPointerCapture(e.pointerId);const x=e.clientX,w=leftWidth;const move=(ev:PointerEvent)=>setLeftWidth(Math.max(190,Math.min(430,w+ev.clientX-x)));const stop=()=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",stop);};window.addEventListener("pointermove",move);window.addEventListener("pointerup",stop);}}/>}
   <main className="work-main">{!path?<Empty onOpen={()=>void openRepo()} recent={recent}/>:<>{repo?.sequencer?.active&&<div className="sequencer-banner"><span><GitMerge size={17}/>Git operation paused for conflict resolution — {repo.sequencer.merge?"merge":repo.sequencer.rebase?"rebase":repo.sequencer.cherry_pick?"cherry-pick":"revert"} in progress</span><button onClick={()=>void runAction(repo.sequencer.merge?"merge_continue":repo.sequencer.rebase?"rebase_continue":repo.sequencer.cherry_pick?"cherry_pick_continue":"revert_continue")}><Check size={14}/>Continue</button><button onClick={()=>void runAction(repo.sequencer.merge?"merge_abort":repo.sequencer.rebase?"rebase_abort":repo.sequencer.cherry_pick?"cherry_pick_abort":"revert_abort")}><X size={14}/>Abort safely</button></div>}<div className="pane-titlebar"><div className="pane-title-main"><span className="title-accent"/><div><span className="pane-eyebrow">{route==="history"?"VISUAL HISTORY":route==="agents"?"PARALLEL DEVELOPMENT":route==="launchpad"?"COLLABORATION":"WORKSPACE"}</span><h1>{heading[route]}</h1></div>{route==="history"&&<span className="commit-count">{commits.length}{hasMore?"+" :""} commits</span>}</div><div className="pane-tools">{route==="history"?<><span className="scope-badge"><Workflow size={14}/>{refScope==="all"?"All references":first(refScope)}</span><IButton icon={Search} label="Search history" onClick={()=>document.getElementById("history-search")?.focus()}/><IButton icon={RefreshCw} label="Refresh history" onClick={()=>void refresh(path,refScope)}/></>:<IButton icon={RefreshCw} label="Refresh view" onClick={()=>route==="launchpad"?void openProvider():void refresh(path,refScope)}/>}</div></div>
     {route==="history"&&<><div className="graph-headers"><span>GRAPH</span><span>COMMIT MESSAGE</span><span>AUTHOR</span><span>DATE</span><span><IButton icon={Filter} label="Filter history" onClick={()=>document.getElementById("history-search")?.focus()}/></span></div><div className="graph-search-row"><Search size={14}/><input id="history-search" aria-label="Filter visible commits" value={historyQuery} onChange={e=>setHistoryQuery(e.target.value)} placeholder="Find commits by message, author or SHA..."/><span>{historyQuery?"Filtering loaded history":"A connected view of your repository"}</span></div><div className="graph-scroll" ref={graphScrollRef} onScroll={e=>setGraphScrollTop(e.currentTarget.scrollTop)}><div className={"wip-commit"+(wip?" selected":"")} onClick={()=>{setSelection("WIP");setDiff("");setSelectedFile("");}} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==="Enter")setSelection("WIP");}}><span className="wip-glyph"><span className="wip-node"/></span><span className="wip-text"><Pill color="#eeb685">WORKING TREE</Pill><strong>{repo?.stats.total?repo.stats.total+" uncommitted file"+(repo.stats.total===1?"":"s"):"Everything is up to date"}</strong></span><span className="wip-descriptor">Your changes</span><span className="wip-time">Now</span><span/></div>{loading?<div className="history-loading"><LoaderCircle size={22} className="spin"/><span>Reading repository history...</span></div>:filtered.length?<><div aria-hidden="true" style={{height:graphStart*graphRowHeight}}/>{visibleGraph.map(row=>{const attached=refs.filter(r=>row.sha.startsWith(r.sha));return <div key={row.sha} className={"commit-row"+(selection===row.sha?" selected":"")} onClick={()=>void inspectCommit(row)} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==="Enter")void inspectCommit(row);}}><CommitGlyph row={row} focused={selection===row.sha}/><div className="commit-content"><span className="commit-subject">{row.subject}</span>{attached.slice(0,2).map(r=><span key={r.full} className={"branch-label "+r.kind} style={{"--branch-c":branchColor(r.full)} as React.CSSProperties}>{r.current?<Circle size={8} fill="currentColor"/>:null}{r.name}</span>)}</div><span className="commit-author">{row.author}</span><span className="commit-date">{row.date}</span><span className="commit-sha">{short(row.sha)}</span></div>})}<div aria-hidden="true" style={{height:graphBelow}}/></>:<div className="no-results"><Search size={20}/><h3>No matching commits</h3><p>Try another search or load additional history.</p></div>}{hasMore&&<button className="history-more" disabled={histLoading} onClick={()=>void loadMore()}>{histLoading?<LoaderCircle className="spin" size={16}/>:<ArrowDown size={15}/>} Load older commits <span>+350</span></button>}</div></>}
     {route==="worktrees"&&<div className="route-content"><div className="route-description"><GitFork size={24}/><div><h2>Work in parallel without collisions.</h2><p>Each Git worktree shares repository history but has its own working directory and checked-out branch.</p></div></div><div className="worktree-grid">{repo?.worktrees.map(w=><div className="worktree-card" key={w.path}><div className="wt-card-head"><span className="wt-icon"><GitFork size={18}/></span><Pill color={w.main?"#75d9d1":"#b9a3ff"}>{w.main?"MAIN":"LINKED"}</Pill></div><h3>{w.branch||"Detached worktree"}</h3><p>{w.path}</p><div className="wt-card-end"><span><Circle size={8} fill={w.locked?"#e6b27d":"#6fc4ad"} color="transparent"/>{w.locked?"Locked":"Ready"}</span><button onClick={()=>void client.openPath(w.path,"explorer").catch(fail)}>Open folder <ExternalLink size={14}/></button></div>{!w.main&&<div className="wt-extra"><button onClick={()=>void runAction(w.locked?"worktree_unlock":"worktree_lock",w.path)}><ShieldCheck size={12}/>{w.locked?"Unlock":"Lock"}</button><button className="danger" onClick={()=>guardedOperation("worktree_remove","","Remove linked worktree","Git refuses to remove a locked or modified worktree. Deleting a clean worktree removes its directory.",first(w.path),w.path)}><Trash2 size={12}/>Remove</button></div>}</div>)}</div><button className="new-worktree-card" onClick={()=>setDialog({title:"New worktree",description:"Create an isolated working directory and branch. The location defaults to a sibling folder.",label:"New branch name",placeholder:"agent/new-feature",confirmText:"Create worktree",onConfirm:name=>{const target=path.replace(/[\\/][^\\/]+$/,"")+"\\arclane-"+name.replaceAll("/","-");void runAction("worktree_add",target,name);}})}><Plus size={21}/><span>Create a worktree</span><small>A safe place for a parallel task</small></button></div>}
     {route==="launchpad"&&<div className="route-content"><div className="route-description"><GitPullRequest size={25}/><div><h2>Reviews, pull requests and checks.</h2><p>GitHub data is read on demand using your existing GitHub CLI authentication.</p></div><ActionButton icon={RefreshCw} label="Reload GitHub" onClick={()=>void openProvider()} busy={providerLoading}/></div><div className="launch-sections"><div className="data-section"><div className="data-section-head"><h3>Open pull requests</h3><span>{prs.length}</span></div>{prs.length?prs.map(pr=><button className="provider-item" key={pr.number} onClick={()=>void client.openExternal(pr.url).catch(fail)}><GitPullRequest size={17}/><span className="provider-text"><strong>{pr.title}</strong><small>#{pr.number} · {pr.headRefName} → {pr.baseRefName}</small></span>{pr.isDraft&&<Pill color="#9babc2">DRAFT</Pill>}<ExternalLink size={14}/></button>):<div className="empty-provider">No open PRs returned. Connect GitHub using <code>gh auth login</code> if required.</div>}</div><div className="data-section"><div className="data-section-head"><h3>Workflow runs</h3><span>{runs.length}</span></div>{runs.length?runs.map(r=><button className="provider-item" key={r.databaseId} onClick={()=>void client.openExternal(r.url).catch(fail)}><Activity size={17}/><span className="provider-text"><strong>{r.displayTitle}</strong><small>{r.workflowName} · {r.headBranch}</small></span><Pill color={r.conclusion==="success"?"#71c3a2":r.conclusion==="failure"?"#f28d90":"#dcb879"}>{r.conclusion||r.status}</Pill><ExternalLink size={14}/></button>):<div className="empty-provider">No workflow runs loaded.</div>}</div></div></div>}
     {route==="agents"&&<div className="route-content"><div className="route-description"><Braces size={25}/><div><h2>Keep agent work isolated.</h2><p>Git worktrees give each coding agent a dedicated branch and folder. Arclane does not run an AI model in the background.</p></div></div><div className="agent-list">{repo?.worktrees.map(w=><div className="agent-card" key={w.path}><span className="agent-worktree-icon"><GitFork size={19}/></span><div><strong>{w.branch||first(w.path)}</strong><small>{w.path}</small></div><Pill color="#81bcb6">WORKTREE</Pill><button onClick={()=>showTerminal(w.path)}><Terminal size={14}/> Open terminal</button></div>)}</div><div className="notice"><ShieldCheck size={19}/><span>Agent status and permission control require explicit agent integrations. No session status is guessed from the presence of a worktree.</span></div></div>}
     {route==="settings"&&<div className="route-content settings-view"><div className="route-description"><Settings2 size={25}/><div><h2>A workspace shaped around your workflow.</h2><p>All preferences remain on this machine.</p></div></div><div className="settings-row"><div><h3>Appearance</h3><p>Choose the contrast that works best for your screen.</p></div><div className="setting-options"><button className={theme==="dark"?"selected":""} onClick={()=>setTheme("dark")}>Dark</button><button className={theme==="light"?"selected":""} onClick={()=>setTheme("light")}>Light</button></div></div><div className="settings-row"><div><h3>Background activity</h3><p>Manual refresh. No repo polling, no automatic fetch, no AI inference service.</p></div><Pill color="#72c9ad">DISABLED</Pill></div><div className="settings-row"><div><h3>Current backend</h3><p>Git for Windows, invoked by Rust using argument arrays without shell interpolation.</p></div><Pill color="#b8a5ff">RUST</Pill></div><div className="settings-row"><div><h3>Repository folder</h3><p>{path}</p></div><button className="outline-action" onClick={()=>void client.openPath(path,"explorer").catch(fail)}><Folder size={14}/>Open folder</button></div></div>}
   </>}</main>
   {path&&<div className="resize-rail right-resizer" role="separator" title="Resize inspector" onPointerDown={e=>{e.currentTarget.setPointerCapture(e.pointerId);const x=e.clientX,w=rightWidth;const move=(ev:PointerEvent)=>setRightWidth(Math.max(302,Math.min(610,w-(ev.clientX-x))));const stop=()=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",stop);};window.addEventListener("pointermove",move);window.addEventListener("pointerup",stop);}}/>}
   {path&&<aside className="inspector"><div className="inspector-head"><span className="pane-eyebrow">INSPECTOR</span><div className="inspector-title"><div><h2>{wip?"Working changes":"Commit details"}</h2><span>{wip?(repo?.files.length||0)+" files changed":currentCommit?short(currentCommit.sha):"Select a commit"}</span></div><IButton icon={MoreHorizontal} label="Inspector actions" onClick={()=>setPaletteOpen(true)}/></div></div>
     {wip?<><div className="change-groups"><div className="change-group-head"><span><Circle size={7} fill="#eba978" color="#eba978"/> Unstaged changes</span><span>{unstaged.length}</span><button disabled={!unstaged.length||!!busy||(repo?.stats.conflicts||0)>0} title={(repo?.stats.conflicts||0)>0?"Resolve merge conflicts first":"Stage all changes"} onClick={stageAll}>Stage all</button></div>{renderFiles(unstaged,false)}<div className="change-group-head staged-head"><span><Circle size={7} fill="#70cdb1" color="#70cdb1"/> Staged changes</span><span>{staged.length}</span><button disabled={!staged.length||!!busy} title="Unstage everything" onClick={()=>void runAction("unstage_all")}>Unstage all</button></div>{renderFiles(staged,true)}</div><div className="right-diff"><div className="right-diff-heading"><FileDiff size={14}/><span>{diffTitle||"Diff preview"}</span>{comparison&&<button className="diff-expand" title="Open wide side-by-side diff" aria-label="Expand diff" onClick={()=>setExpandedDiff(true)}><Maximize2 size={14}/></button>}{selectedFile&&<div className="diff-mode-tabs">{comparison&&<button className={diffMode==="side"?"active":""} onClick={()=>setDiffMode("side")}><Columns2 size={12}/> Side by side</button>}<button className={diffMode==="patch"?"active":""} onClick={()=>setDiffMode("patch")}>Patch</button><button className={diffMode==="hunks"?"active":""} onClick={()=>setDiffMode("hunks")}>Hunks {hunks.length}</button></div>}</div>{diffMode==="side"&&comparison?<SideBySideDiff comparison={comparison}/>:diffMode==="hunks"&&selectedFile&&hunks.length>0?<div className="hunk-list">{hunks.map(h=><section key={h.index} className="hunk-card"><div className="hunk-head"><span><GitBranch size={12}/>{h.header}</span><small>+{h.added} / -{h.removed}</small><button disabled={!!busy} onClick={()=>void stageHunk(h.index)}>{selectedFile.endsWith("#staged")?<Minus size={13}/>:<Plus size={13}/>} {selectedFile.endsWith("#staged")?"Unstage":"Stage"} hunk</button></div><pre>{h.text}</pre></section>)}</div>:<DiffLines text={diff}/>}</div><div className="commit-composer"><div className="composer-head"><GitCommitHorizontal size={16}/><b>Commit changes</b>{staged.length>0&&<Pill color="#75d9b9">{staged.length} staged</Pill>}</div><input aria-label="Commit summary" placeholder="Summary of what changed" value={commitText} onChange={e=>setCommitText(e.target.value)} maxLength={300}/><textarea aria-label="Commit description" placeholder="Add a description (optional)" value={commitBody} onChange={e=>setCommitBody(e.target.value)} rows={3}/><button className="commit-submit" disabled={!commitText.trim()||staged.length===0||!!busy||(repo?.stats.conflicts||0)>0} onClick={commit}>{busy==="commit"?<LoaderCircle className="spin" size={16}/>:<GitCommitHorizontal size={17}/>}Commit {staged.length>0?staged.length+" staged file"+(staged.length===1?"":"s"):"staged changes"}<ArrowRight size={16}/></button></div></>:<div className="commit-inspector">{currentCommit?<><div className="commit-meta"><span className="meta-label">COMMIT</span><h3>{currentCommit.subject}</h3><div className="meta-row"><span>SHA</span><button className="copy-sha" onClick={()=>{void navigator.clipboard.writeText(currentCommit.sha);showToast("Commit SHA copied");}}>{short(currentCommit.sha)}<Copy size={12}/></button></div><div className="meta-row"><span>Author</span><strong>{currentCommit.author}</strong></div><div className="meta-row"><span>Committed</span><strong>{currentCommit.date}</strong></div><div className="meta-row"><span>Parents</span><strong>{currentCommit.parents.length}</strong></div></div><div className="commit-context-actions"><button onClick={()=>void runAction("cherry_pick",null,currentCommit.sha)}><GitCommitHorizontal size={14}/> Cherry-pick</button><button onClick={()=>guardedOperation("revert",currentCommit.sha,"Revert commit","Create a reversing commit.",short(currentCommit.sha))}><Undo2 size={14}/> Revert</button><button onClick={()=>guardedOperation("reset_soft",currentCommit.sha,"Soft reset","Move HEAD to this commit. Keep index and working files.",short(currentCommit.sha))}><GitBranch size={14}/> Reset soft</button></div><div className="commit-diff-header"><FileDiff size={15}/> Changes in commit</div><div className="commit-patch"><DiffLines text={diff}/></div></>:<BlankRoute icon={GitCommitHorizontal} title="Select a commit" body="Select a point in the history to inspect its contents and ancestry."/>}</div>}
   </aside>}
  </div>
  {terminalDockOpen&&<TerminalDock request={terminalRequest} onClose={()=>setTerminalDockOpen(false)}/>}
  {expandedDiff&&comparison&&<div className="diff-expand-overlay" role="dialog" aria-modal="true" aria-label={"Side-by-side comparison "+comparison.file}><div className="diff-expand-frame"><div className="diff-expand-heading"><span><Columns2 size={18}/><strong>Side-by-side comparison</strong><small>{comparison.file}</small></span><button aria-label="Close expanded diff" onClick={()=>setExpandedDiff(false)}><X size={19}/></button></div><SideBySideDiff comparison={comparison}/></div></div>}
  {insightsFile&&path&&<FileInsights path={path} file={insightsFile} onClose={()=>setInsightsFile(null)}/>}
  {conflictFile&&path&&<ConflictResolver path={path} file={conflictFile} onClose={()=>setConflictFile(null)} onResolved={file=>{setConflictFile(null);void refresh(path,refScope);showToast("Resolved and staged "+file);}}/>}
  <footer className="statusbar"><span className="status-left"><Circle size={6} fill={error?"#f19698":"#76c5a8"} color="transparent"/>{error?"Attention required":loading?"Reading repository":"Ready"}<span className="status-divider"/>{path?first(path):"No repository selected"}</span><span className="status-right"><span><HardDrive size={12}/> LOCAL FIRST</span><span><ShieldCheck size={12}/> SAFE GIT</span><span>ARCLANE 0.1</span></span></footer>
  {error&&<div className="toast error-toast"><span><ShieldCheck size={16}/>{error}</span><IButton icon={X} label="Dismiss error" onClick={()=>setError("")}/></div>}
  {success&&<div className="toast success-toast"><Check size={17}/>{success}</div>}
  {dialog&&<Dialog dialog={dialog} onClose={()=>setDialog(null)}/>}
  {paletteOpen&&<div className="palette-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setPaletteOpen(false);}}><div className="palette" role="dialog" aria-modal="true" aria-label="Command palette"><div className="palette-search"><Command size={20}/><input autoFocus value={paletteQuery} placeholder="What would you like to do?" onChange={e=>setPaletteQuery(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){const a=actions.find(a=>a.name.toLowerCase().includes(paletteQuery.toLowerCase()));if(a){a.perform();setPaletteOpen(false);setPaletteQuery("");}}}}/><kbd>ESC</kbd></div><div className="palette-results"><div className="palette-caption">ACTIONS</div>{actions.filter(a=>a.name.toLowerCase().includes(paletteQuery.toLowerCase())).map(a=><button key={a.name} onClick={()=>{a.perform();setPaletteOpen(false);setPaletteQuery("");}}><a.icon size={18}/><span>{a.name}</span>{a.shortcut&&<kbd>{a.shortcut}</kbd>}<ArrowRight size={14}/></button>)}{!actions.some(a=>a.name.toLowerCase().includes(paletteQuery.toLowerCase()))&&<div className="palette-none">No matching actions</div>}</div><div className="palette-footer"><span>↑ ↓ Navigate</span><span>↵ Run action</span></div></div></div>}
 </div>;
}
